// components/ScriptReader.js

import React, { useState, useCallback } from 'react';
import { FileText, UploadCloud } from 'lucide-react';

const ScriptReader = () => {
  const [file, setFile] = useState(null);
  const [fileName, setFileName] = useState('');

  const handleFileUpload = useCallback((event) => {
    const uploadedFile = event.target.files[0];
    if (uploadedFile) {
      setFile(uploadedFile);
      setFileName(uploadedFile.name);
    } else {
      setFile(null);
      setFileName('');
    }
  }, [setFile, setFileName]);

  return (
    <div className="p-6 max-w-4xl mx-auto text-white">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-2xl font-bold flex items-center gap-2">
          <FileText className="w-6 h-6 text-accent" />
          Script Viewer
        </h2>
        <label className="cursor-pointer inline-flex items-center gap-2 px-4 py-2 bg-primary rounded hover:bg-primaryDark transition">
          <UploadCloud className="w-5 h-5" />
          Upload Script
          <input
            type="file"
            accept=".doc,.docx"
            onChange={handleFileUpload}
            className="hidden" // Hide the default file input
          />
        </label>
      </div>
      <div className="bg-secondaryLight p-4 rounded shadow max-h-[70vh] overflow-y-auto flex flex-col items-center justify-center gap-4">
        {file ? (
          <div>
            <p className="text-midGray italic">Selected: {fileName}</p>
            <p className="text-sm text-center">
              To view online, please upload to one of the following services and then use the sharing link:
            </p>
            <div className="flex gap-4 mt-2">
              <a
                href="https://drive.google.com/"
                target="_blank"
                rel="noopener noreferrer"
                className="text-accent hover:underline"
              >
                Open in Google Drive
              </a>
              <a
                href="https://onedrive.live.com/"
                target="_blank"
                rel="noopener noreferrer"
                className="text-accent hover:underline"
              >
                Open in OneDrive
              </a>
              {/* Add more online viewer links as needed */}
            </div>
          </div>
        ) : (
          <p className="text-midGray italic">Upload a `.doc` or `.docx` file to get options for online viewing.</p>
        )}
      </div>
    </div>
  );
};

export default ScriptReader;
